use hec_native_ic::fp::Fp;use std::collections::BTreeMap;
#[derive(Clone,Debug)]pub struct Proof{pub excluded:bool,pub k:u64,pub w:Vec<u64>}
type V=BTreeMap<usize,u64>;
fn product(f:&Fp,a:u64,b:u64)->u64{if a==0||b==0{0}else if a==1{b}else if b==1{a}else if a==f.p-1{f.neg(b)}else if b==f.p-1{f.neg(a)}else{f.mul(a,b)}}
fn subtract(f:&Fp,a:&mut V,b:&V,w:u64){for(&i,&v)in b{let x=f.sub(*a.get(&i).unwrap_or(&0),product(f,w,v));if x==0{a.remove(&i);}else{a.insert(i,x);}}}
fn dense(w:V,size:usize)->Vec<u64>{let mut v=vec![0;size];for(i,x)in w{v[i]=x;}v}
fn prove_flat(rows:&[(Vec<u64>,u64)],n:usize,f:&Fp)->Proof{let mut basis:Vec<Option<(V,V)>>=vec![None;n];for(i,(v,b))in rows.iter().enumerate(){let mut a:V=v.iter().copied().chain(std::iter::once(*b)).enumerate().filter(|(_,x)|*x!=0).collect();let mut w=V::from([(i,1)]);loop{let Some((&j,&scale))=a.first_key_value()else{break};if j==n{let iv=if scale==1{1}else{f.inv(scale)};for x in w.values_mut(){*x=product(f,*x,iv)}return Proof{excluded:true,k:1,w:dense(w,rows.len())}}if let Some((q,z))=&basis[j]{subtract(f,&mut a,q,scale);subtract(f,&mut w,z,scale);}else{let iv=if scale==1{1}else{f.inv(scale)};for x in a.values_mut(){*x=product(f,*x,iv)}for x in w.values_mut(){*x=product(f,*x,iv)}basis[j]=Some((a,w));break}}}let(a,w)=basis[n-1].as_ref().expect("unresolved branch");Proof{excluded:false,k:*a.get(&n).unwrap_or(&0),w:dense(w.clone(),rows.len())}}
pub fn verify(rows:&[(Vec<u64>,u64)],n:usize,f:&Fp,p:&Proof)->bool{if p.w.len()!=rows.len()||p.w.iter().any(|x|*x>=f.p)||p.k>=f.p{return false}let mut sum=vec![0;n];let mut rhs=0;for((a,b),&w)in rows.iter().zip(&p.w){if w==0{continue}for j in 0..n{if a[j]!=0{sum[j]=f.add(sum[j],product(f,w,a[j]));}}if *b!=0{rhs=f.add(rhs,product(f,w,*b));}}if p.excluded{sum.iter().all(|x|*x==0)&&rhs==1&&p.k==1}else{let mut e=vec![0;n];e[n-1]=1;sum==e&&rhs==p.k}}
fn add_scaled(f:&Fp,a:&mut V,b:&V,w:u64){if w==0{return}for(&i,&v)in b{let x=f.add(*a.get(&i).unwrap_or(&0),product(f,w,v));if x==0{a.remove(&i);}else{a.insert(i,x);}}}
// P_j = L_j(S,T,1) + provenance_j*(A P-b), for each action component.
pub fn prove(rows:&[(Vec<u64>,u64)],n:usize,f:&Fp)->Proof{assert!(n>=3);assert_eq!(rows[0].0[0],1);assert!(rows[0].0[1..].iter().all(|x|*x==0));let mut labels=vec![None;n-1];let mut proofs=vec![V::new();n-1];labels[0]=Some([0,0,rows[0].1]);proofs[0].insert(0,1);labels[1]=Some([1,0,0]);let mut constraints=vec![];let mut provenance=vec![];
for(i,(row,rhs))in rows.iter().enumerate().skip(1){let mut l=[0,row[n-1],f.neg(*rhs)];let mut p=V::from([(i,1)]);let mut unknown=None;for j in 0..n-1{let w=row[j];if w==0{continue}if let Some(label)=labels[j]{for k in 0..3{l[k]=f.add(l[k],product(f,w,label[k]));}add_scaled(f,&mut p,&proofs[j],f.neg(w));}else{assert!(unknown.is_none(),"nontriangular primitive");unknown=Some((j,w));}}
if let Some((j,w))=unknown{let iv=if w==1{1}else{f.inv(w)};labels[j]=Some(l.map(|x|product(f,f.neg(x),iv)));for x in p.values_mut(){*x=product(f,*x,iv)}proofs[j]=p;}else{constraints.push((l[..2].to_vec(),f.neg(l[2])));provenance.push(p);}}
let small=prove_flat(&constraints,2,f);let mut combined=V::new();for(i,w)in small.w.into_iter().enumerate(){add_scaled(f,&mut combined,&provenance[i],w);}Proof{excluded:small.excluded,k:small.k,w:dense(combined,rows.len())}}
